    private int extractArchive(byte[] archive, Path uploadDir) throws IOException {
        int entryCount = 0;
        try (ZipInputStream zipStream = new ZipInputStream(new ByteArrayInputStream(archive))) {
            ZipEntry entry;
            while ((entry = zipStream.getNextEntry()) != null) {
                entryCount++;
                String entryName = entry.getName();
                if (entryName == null || entryName.isEmpty()) {
                    zipStream.closeEntry();
                    continue;
                }
                Path target = uploadDir.resolve(entryName).normalize();
                if (!target.startsWith(uploadDir)) {
                    zipStream.closeEntry();
                    continue;
                }
                if (entry.isDirectory()) {
                    Files.createDirectories(target);
                } else {
                    Path parent = target.getParent();
                    if (parent != null) {
                        Files.createDirectories(parent);
                    }
                    Files.copy(zipStream, target, StandardCopyOption.REPLACE_EXISTING);
                }
                zipStream.closeEntry();
            }
        }
        return entryCount;
    }
